import 'package:flutter/material.dart';import 'package:uuid/uuid.dart';import '../../models/comment.dart';import '../../services/demo_store.dart';
class CommentsScreen extends StatefulWidget{final String partyId;const CommentsScreen({super.key,required this.partyId});@override State<CommentsScreen>createState()=>_CommentsScreenState();}class _CommentsScreenState extends State<CommentsScreen>{final t=TextEditingController();final s=DemoStore.instance;@override void initState(){super.initState();s.init();s.comments[s.initComments(widget.partyId)]??=[];}@override void dispose(){t.dispose();super.dispose();}@override Widget build(BuildContext c){final list=s.comments[widget.partyId]??[];return Scaffold(appBar:AppBar(title:const Text('Comments')),body:Column(children:[Expanded(child:ListView(children:list.map((x)=>ListTile(leading:const CircleAvatar(child:Icon(Icons.person)),title:Text(x.content),subtitle:Text('@${x.username??'user'}'))).toList())),SafeArea(child:Row(children:[Expanded(child:TextField(controller:t,maxLength:500,decoration:const InputDecoration(hintText:'Add a comment'))),IconButton(onPressed:(){if(t.text.trim().isEmpty)return;setState((){list.add(Comment(id:const Uuid().v4(),mediaId:'',userId:'demo-user',content:t.text.trim(),createdAt:DateTime.now().toUtc(),updatedAt:DateTime.now().toUtc(),username:'picparty_user'));t.clear();});},icon:const Icon(Icons.send))]))]));}}
extension _CommentsInit on DemoStore{String initComments(String id){comments[id]??=[];return id;}}
